import { z } from "zod";

/**
 * Resume JSON schema 2.0 — prd.md §6. One canonical schema for
 * extraction, editing, generation, scoring, rendering and PDF export.
 *
 * - Ids are short stable strings (`we_1`, `b_3`) generated by the app
 *   (see ids.ts), never by the model. Ids from the original are kept in
 *   generated versions, which is what the grounding check (§8.3) and
 *   provenance rely on.
 * - Dates are `{ value: "YYYY-MM" | "YYYY" | null, raw }`; `raw` keeps
 *   what the resume said ("Summer 2021").
 * - String fields default to "" and lists to [], so a partly extracted
 *   resume is still valid; what the editor *requires* (name, a contact,
 *   company + designation) is checked by `editorIssues`, not here.
 * - The same schema generates the OpenAI Structured Outputs schema
 *   (structured-output.ts) — there is no hand-written copy.
 */

export const RESUME_SCHEMA_VERSION = "2.0";

/** App-generated id: lowercase prefix, underscore, number. */
export const itemIdSchema = z
  .string()
  .regex(/^[a-z][a-z0-9]*_[0-9]+$/, "Ids are app-generated, like we_1 or b_3");

const text = (max: number) => z.string().max(max).default("");

/** `YYYY-MM` (month known) or `YYYY` (year only). */
export const DATE_VALUE_PATTERN = /^(19|20)\d{2}(-(0[1-9]|1[0-2]))?$/;

export const resumeDateSchema = z.object({
  value: z.string().regex(DATE_VALUE_PATTERN, "Dates are YYYY-MM or YYYY").nullable().default(null),
  raw: text(100),
});

const bulletSchema = z.object({ id: itemIdSchema, text: text(1000) });

export const LINK_TYPES = ["linkedin", "github", "portfolio", "other"] as const;
export const EMPLOYMENT_TYPES = [
  "full-time",
  "part-time",
  "contract",
  "internship",
  "freelance",
] as const;
export const BULLET_KINDS = ["responsibility", "achievement"] as const;
export const GRADE_SCALES = ["CGPA/10", "%", "GPA/4", "other"] as const;

export const linkSchema = z.object({
  id: itemIdSchema,
  type: z.enum(LINK_TYPES).default("other"),
  label: text(100),
  url: text(500),
});

export const personalInfoSchema = z.object({
  firstName: text(100),
  lastName: text(100),
  headline: text(200),
  email: text(254),
  phone: text(50),
  location: text(200),
  links: z.array(linkSchema).max(20).default([]),
});

export const workExperienceSchema = z.object({
  id: itemIdSchema,
  company: text(200),
  designation: text(200),
  employmentType: z.enum(EMPLOYMENT_TYPES).nullable().default(null),
  location: text(200),
  startDate: resumeDateSchema.default({ value: null, raw: "" }),
  endDate: resumeDateSchema.default({ value: null, raw: "" }),
  isCurrent: z.boolean().default(false),
  bullets: z
    .array(bulletSchema.extend({ kind: z.enum(BULLET_KINDS).default("responsibility") }))
    .max(50)
    .default([]),
  skillsUsed: z.array(z.string().max(100)).max(50).default([]),
});

export const educationSchema = z.object({
  id: itemIdSchema,
  institution: text(200),
  degree: text(200),
  fieldOfStudy: text(200),
  location: text(200),
  startDate: resumeDateSchema.default({ value: null, raw: "" }),
  endDate: resumeDateSchema.default({ value: null, raw: "" }),
  grade: z
    .object({ value: text(20), scale: z.enum(GRADE_SCALES).nullable().default(null) })
    .default({ value: "", scale: null }),
  bullets: z.array(bulletSchema).max(30).default([]),
});

export const skillGroupSchema = z.object({
  id: itemIdSchema,
  category: text(100),
  items: z
    .array(z.object({ id: itemIdSchema, name: z.string().max(100) }))
    .max(100)
    .default([]),
});

export const projectSchema = z.object({
  id: itemIdSchema,
  name: text(200),
  role: text(200),
  url: text(500),
  startDate: resumeDateSchema.default({ value: null, raw: "" }),
  endDate: resumeDateSchema.default({ value: null, raw: "" }),
  bullets: z.array(bulletSchema).max(30).default([]),
  technologies: z.array(z.string().max(100)).max(50).default([]),
});

export const certificationSchema = z.object({
  id: itemIdSchema,
  name: text(200),
  issuer: text(200),
  issueDate: resumeDateSchema.default({ value: null, raw: "" }),
  expiryDate: resumeDateSchema.default({ value: null, raw: "" }),
  credentialId: text(200),
  credentialUrl: text(500),
});

export const customSectionSchema = z.object({
  id: itemIdSchema,
  title: text(100),
  items: z
    .array(
      z.object({
        id: itemIdSchema,
        heading: text(200),
        subheading: text(200),
        date: resumeDateSchema.default({ value: null, raw: "" }),
        bullets: z.array(bulletSchema).max(30).default([]),
      }),
    )
    .max(50)
    .default([]),
});

export const BUILT_IN_SECTIONS = [
  "summary",
  "workExperience",
  "projects",
  "skills",
  "education",
  "certifications",
] as const;
export type BuiltInSection = (typeof BUILT_IN_SECTIONS)[number];

/** A built-in section key, or `custom:<id>` for a custom section. */
export const sectionKeySchema = z.union([
  z.enum(BUILT_IN_SECTIONS),
  z.string().regex(/^custom:[a-z][a-z0-9]*_[0-9]+$/),
]);

export const DEFAULT_SECTION_ORDER: BuiltInSection[] = [...BUILT_IN_SECTIONS];

export const layoutSchema = z.object({
  sectionOrder: z.array(sectionKeySchema).default(DEFAULT_SECTION_ORDER),
  hiddenSections: z.array(sectionKeySchema).default([]),
  /** Item ids (any section) hidden from the rendered resume. */
  hiddenItems: z.array(itemIdSchema).default([]),
});

/** The resume content, before cross-field checks. */
export const resumeContentShape = z.object({
  schemaVersion: z.literal(RESUME_SCHEMA_VERSION),
  personalInfo: personalInfoSchema.default({
    firstName: "",
    lastName: "",
    headline: "",
    email: "",
    phone: "",
    location: "",
    links: [],
  }),
  summary: z.object({ text: text(3000) }).default({ text: "" }),
  workExperience: z.array(workExperienceSchema).max(30).default([]),
  education: z.array(educationSchema).max(15).default([]),
  skills: z.array(skillGroupSchema).max(30).default([]),
  projects: z.array(projectSchema).max(30).default([]),
  certifications: z.array(certificationSchema).max(30).default([]),
  customSections: z.array(customSectionSchema).max(10).default([]),
  layout: layoutSchema.default({
    sectionOrder: DEFAULT_SECTION_ORDER,
    hiddenSections: [],
    hiddenItems: [],
  }),
});

/** Every item id in a resume, in document order. */
export function collectIds(r: z.output<typeof resumeContentShape>): string[] {
  const ids: string[] = [];
  const bullets = (b: { id: string }[]) => b.forEach((x) => ids.push(x.id));
  r.personalInfo.links.forEach((l) => ids.push(l.id));
  r.workExperience.forEach((w) => (ids.push(w.id), bullets(w.bullets)));
  r.education.forEach((e) => (ids.push(e.id), bullets(e.bullets)));
  r.skills.forEach((s) => (ids.push(s.id), s.items.forEach((i) => ids.push(i.id))));
  r.projects.forEach((p) => (ids.push(p.id), bullets(p.bullets)));
  r.certifications.forEach((c) => ids.push(c.id));
  r.customSections.forEach(
    (c) => (ids.push(c.id), c.items.forEach((i) => (ids.push(i.id), bullets(i.bullets)))),
  );
  return ids;
}

/**
 * The canonical schema: content plus the checks that span fields —
 * unique ids, an end date never before its start, `isCurrent` meaning
 * Present, and a layout that only points at sections and items that
 * exist.
 */
export const resumeSchema = resumeContentShape.superRefine((r, ctx) => {
  const ids = collectIds(r);
  const seen = new Set<string>();
  for (const id of ids) {
    if (seen.has(id))
      ctx.addIssue({ code: "custom", message: `Duplicate id "${id}"`, path: ["ids"] });
    seen.add(id);
  }

  const dated: [string, number, { value: string | null }, { value: string | null }][] = [
    ...r.workExperience.map(
      (w, i) =>
        ["workExperience", i, w.startDate, w.endDate] as [
          string,
          number,
          typeof w.startDate,
          typeof w.endDate,
        ],
    ),
    ...r.education.map(
      (e, i) =>
        ["education", i, e.startDate, e.endDate] as [
          string,
          number,
          typeof e.startDate,
          typeof e.endDate,
        ],
    ),
    ...r.projects.map(
      (p, i) =>
        ["projects", i, p.startDate, p.endDate] as [
          string,
          number,
          typeof p.startDate,
          typeof p.endDate,
        ],
    ),
  ];
  for (const [section, i, start, end] of dated) {
    // Compare on the shared precision: "2021" vs "2021-06" is fine.
    if (
      start.value &&
      end.value &&
      end.value.slice(0, Math.min(start.value.length, end.value.length)) <
        start.value.slice(0, Math.min(start.value.length, end.value.length))
    ) {
      ctx.addIssue({
        code: "custom",
        message: "End date is before start date",
        path: [section, i, "endDate"],
      });
    }
  }
  r.workExperience.forEach((w, i) => {
    if (w.isCurrent && w.endDate.value !== null) {
      ctx.addIssue({
        code: "custom",
        message: "A current job has no end date (Present)",
        path: ["workExperience", i, "endDate"],
      });
    }
  });

  const customKeys = new Set(r.customSections.map((c) => `custom:${c.id}`));
  const validSection = (key: string) =>
    (BUILT_IN_SECTIONS as readonly string[]).includes(key) || customKeys.has(key);
  r.layout.sectionOrder.forEach((key, i) => {
    if (!validSection(key))
      ctx.addIssue({
        code: "custom",
        message: `Unknown section "${key}"`,
        path: ["layout", "sectionOrder", i],
      });
  });
  if (new Set(r.layout.sectionOrder).size !== r.layout.sectionOrder.length) {
    ctx.addIssue({
      code: "custom",
      message: "A section appears twice in sectionOrder",
      path: ["layout", "sectionOrder"],
    });
  }
  r.layout.hiddenSections.forEach((key, i) => {
    if (!validSection(key))
      ctx.addIssue({
        code: "custom",
        message: `Unknown section "${key}"`,
        path: ["layout", "hiddenSections", i],
      });
  });
  r.layout.hiddenItems.forEach((id, i) => {
    if (!seen.has(id))
      ctx.addIssue({
        code: "custom",
        message: `Unknown item "${id}"`,
        path: ["layout", "hiddenItems", i],
      });
  });
});

export type Resume = z.output<typeof resumeSchema>;
export type ResumeInput = z.input<typeof resumeSchema>;
export type ResumeDate = z.output<typeof resumeDateSchema>;
export type WorkExperience = z.output<typeof workExperienceSchema>;

// --- §6.2: metadata stored beside the content (never sent to templates) ---

/**
 * Field path into the resume, addressing items by id so it survives
 * reordering: `workExperience[id=we_1].startDate`, `personalInfo.email`.
 */
export const fieldPathSchema = z
  .string()
  .max(200)
  .regex(
    /^[a-zA-Z]+(\[id=[a-z][a-z0-9]*_[0-9]+\])?(\.[a-zA-Z]+(\[id=[a-z][a-z0-9]*_[0-9]+\])?)*$/,
    "Invalid field path",
  );

export const extractionMetaSchema = z.record(
  fieldPathSchema,
  z.object({
    confidence: z.enum(["low", "medium"]),
    reason: z.string().max(300),
    reviewed: z.boolean().default(false),
    /**
     * Where the doubt comes from, so a flag is traceable (prd.md §5.3
     * step 5): the OCR line the field was read from and its confidence,
     * or `text` when the value couldn't be found in the source at all.
     */
    source: z
      .object({
        kind: z.enum(["ocr_line", "not_in_source", "partial_date"]),
        page: z.number().int().positive().optional(),
        line: z.string().max(500).optional(),
        ocrConfidence: z.number().min(0).max(100).optional(),
      })
      .optional(),
  }),
);

/** Provenance key: `<itemId>.bullets[<bulletId>]`, e.g. `we_1.bullets[b_3]`. */
export const provenanceKeySchema = z
  .string()
  .regex(/^[a-z][a-z0-9]*_[0-9]+\.bullets\[[a-z][a-z0-9]*_[0-9]+\]$/);

export const provenanceSchema = z.record(
  provenanceKeySchema,
  z.object({
    sourceBulletIds: z.array(itemIdSchema).min(1),
    changeType: z.enum(["rewritten", "reordered", "unchanged", "merged"]),
  }),
);

export const resumeMetaSchema = z.object({
  extractionMeta: extractionMetaSchema.default({}),
  provenance: provenanceSchema.default({}),
});

export type ExtractionMeta = z.output<typeof extractionMetaSchema>;
export type Provenance = z.output<typeof provenanceSchema>;
export type ResumeMeta = z.output<typeof resumeMetaSchema>;

/** The review screen blocks generation until every `low` field is reviewed (§6.2). */
export function unreviewedLowConfidence(meta: ExtractionMeta): string[] {
  return Object.entries(meta)
    .filter(([, m]) => m.confidence === "low" && !m.reviewed)
    .map(([path]) => path);
}

export interface EditorIssue {
  path: string;
  message: string;
}

/**
 * §6.3: the fields the editor requires — a name, at least one contact
 * method, and company + designation on every job. Separate from the
 * schema so partial extractions are still storable.
 */
export function editorIssues(r: Resume): EditorIssue[] {
  const issues: EditorIssue[] = [];
  if (!r.personalInfo.firstName.trim() && !r.personalInfo.lastName.trim()) {
    issues.push({ path: "personalInfo.firstName", message: "Add your name." });
  }
  if (
    !r.personalInfo.email.trim() &&
    !r.personalInfo.phone.trim() &&
    r.personalInfo.links.length === 0
  ) {
    issues.push({ path: "personalInfo.email", message: "Add at least one way to contact you." });
  }
  for (const w of r.workExperience) {
    if (!w.company.trim())
      issues.push({ path: `workExperience[id=${w.id}].company`, message: "Add the company." });
    if (!w.designation.trim()) {
      issues.push({
        path: `workExperience[id=${w.id}].designation`,
        message: "Add your job title.",
      });
    }
  }
  return issues;
}
